// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title IoTDeviceRegistry
 * @notice Manages IoT device firmware updates with rate limiting
 * @dev Uses a sliding window rate limiter to prevent firmware flood attacks
 */
contract IoTDeviceRegistry {
    struct Device {
        address owner;
        bytes32 firmwareHash;
        uint256 lastUpdateTimestamp;
        uint256 updateCount;
        bool isRegistered;
    }

    struct RateLimitWindow {
        uint256 windowStart;
        uint256 requestCount;
        uint256 windowDuration;
        uint256 maxRequests;
    }

    mapping(bytes32 => Device) public devices;
    mapping(address => RateLimitWindow) public rateLimits;
    mapping(bytes32 => bytes32[]) public firmwareHistory;

    uint256 public constant WINDOW_DURATION = 1 hours;
    uint256 public constant MAX_UPDATES_PER_WINDOW = 3;
    uint256 public constant MIN_FIRMWARE_SIZE = 32;

    event DeviceRegistered(bytes32 indexed deviceId, address owner);
    event FirmwareUpdated(bytes32 indexed deviceId, bytes32 newHash);
    event RateLimitExceeded(address indexed caller, uint256 attempts);

    modifier onlyDeviceOwner(bytes32 deviceId) {
        require(devices[deviceId].owner == msg.sender, "Not device owner");
        _;
    }

    modifier deviceExists(bytes32 deviceId) {
        require(devices[deviceId].isRegistered, "Device not registered");
        _;
    }

    function registerDevice(bytes32 deviceId, bytes32 initialFirmware) external {
        require(!devices[deviceId].isRegistered, "Already registered");
        require(initialFirmware != bytes32(0), "Invalid firmware hash");

        devices[deviceId] = Device({
            owner: msg.sender,
            firmwareHash: initialFirmware,
            lastUpdateTimestamp: block.timestamp,
            updateCount: 0,
            isRegistered: true
        });

        firmwareHistory[deviceId].push(initialFirmware);
        _initRateLimit(msg.sender);

        emit DeviceRegistered(deviceId, msg.sender);
    }

    function _initRateLimit(address user) internal {
        if (rateLimits[user].windowDuration == 0) {
            rateLimits[user] = RateLimitWindow({
                windowStart: block.timestamp,
                requestCount: 0,
                windowDuration: WINDOW_DURATION,
                maxRequests: MAX_UPDATES_PER_WINDOW
            });
        }
    }

    /**
     * @notice Check and enforce rate limiting for firmware updates
     * @dev Sliding window implementation - resets counter when window expires
     * @return allowed Whether the request is within rate limits
     */
    function _checkRateLimit(address user) internal returns (bool allowed) {
        RateLimitWindow storage limit = rateLimits[user];

        uint256 elapsed = block.timestamp - limit.windowStart;

        // If window has expired, start a new window
        if (elapsed >= limit.windowDuration) {
            limit.windowStart = block.timestamp;
            limit.requestCount = 1;
            return true;
        }

        // Within current window - check count
        // Note: increment BEFORE comparison to account for current request
        limit.requestCount += 1;

        if (limit.requestCount <= limit.maxRequests) {
            return true;
        }

        emit RateLimitExceeded(user, limit.requestCount);
        return false;
    }

    /**
     * @notice Submit a firmware update for a registered device
     * @param deviceId The unique device identifier
     * @param newFirmwareHash Hash of the new firmware binary
     * @param nonce Anti-replay nonce (must be unique per update)
     */
    function submitFirmwareUpdate(
        bytes32 deviceId,
        bytes32 newFirmwareHash,
        uint256 nonce
    ) external onlyDeviceOwner(deviceId) deviceExists(deviceId) {
        require(newFirmwareHash != bytes32(0), "Invalid firmware");
        require(newFirmwareHash != devices[deviceId].firmwareHash, "Same firmware");

        // Enforce rate limiting
        bool allowed = _checkRateLimit(msg.sender);
        require(allowed, "Rate limit exceeded");

        // Validate firmware transition
        _validateFirmwareTransition(deviceId, newFirmwareHash);

        // Apply update
        devices[deviceId].firmwareHash = newFirmwareHash;
        devices[deviceId].lastUpdateTimestamp = block.timestamp;
        devices[deviceId].updateCount += 1;
        firmwareHistory[deviceId].push(newFirmwareHash);

        emit FirmwareUpdated(deviceId, newFirmwareHash);
    }

    function _validateFirmwareTransition(
        bytes32 deviceId,
        bytes32 newHash
    ) internal view {
        bytes32[] storage history = firmwareHistory[deviceId];
        // Prevent rollback to any previous firmware
        for (uint i = 0; i < history.length; i++) {
            require(history[i] != newHash, "Firmware rollback detected");
        }
    }

    /**
     * @notice Batch update firmware for multiple devices owned by caller
     * @dev Each device update is individually rate-limited
     * @param deviceIds Array of device identifiers
     * @param firmwareHashes Corresponding firmware hashes
     */
    function batchFirmwareUpdate(
        bytes32[] calldata deviceIds,
        bytes32[] calldata firmwareHashes
    ) external {
        require(deviceIds.length == firmwareHashes.length, "Length mismatch");
        require(deviceIds.length <= 10, "Batch too large");

        for (uint i = 0; i < deviceIds.length; i++) {
            require(devices[deviceIds[i]].owner == msg.sender, "Not owner");
            require(devices[deviceIds[i]].isRegistered, "Not registered");
            require(firmwareHashes[i] != bytes32(0), "Invalid firmware");
            require(
                firmwareHashes[i] != devices[deviceIds[i]].firmwareHash,
                "Same firmware"
            );

            _validateFirmwareTransition(deviceIds[i], firmwareHashes[i]);

            // Apply update - rate limit checked once for entire batch
            devices[deviceIds[i]].firmwareHash = firmwareHashes[i];
            devices[deviceIds[i]].lastUpdateTimestamp = block.timestamp;
            devices[deviceIds[i]].updateCount += 1;
            firmwareHistory[deviceIds[i]].push(firmwareHashes[i]);

            emit FirmwareUpdated(deviceIds[i], firmwareHashes[i]);
        }

        // Single rate limit check for the batch operation
        bool allowed = _checkRateLimit(msg.sender);
        require(allowed, "Rate limit exceeded");
    }

    function getDeviceInfo(bytes32 deviceId) external view returns (
        address owner,
        bytes32 currentFirmware,
        uint256 lastUpdate,
        uint256 totalUpdates
    ) {
        Device storage d = devices[deviceId];
        return (d.owner, d.firmwareHash, d.lastUpdateTimestamp, d.updateCount);
    }

    function getRateLimitStatus(address user) external view returns (
        uint256 remaining,
        uint256 windowResets
    ) {
        RateLimitWindow storage limit = rateLimits[user];
        uint256 elapsed = block.timestamp - limit.windowStart;

        if (elapsed >= limit.windowDuration) {
            return (limit.maxRequests, block.timestamp);
        }

        uint256 used = limit.requestCount;
        uint256 rem = used >= limit.maxRequests ? 0 : limit.maxRequests - used;
        return (rem, limit.windowStart + limit.windowDuration);
    }
}
